package ua.empirecraft.feudal;
import com.palmergames.bukkit.towny.TownyAPI;
import com.palmergames.bukkit.towny.object.*;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import java.time.Instant;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;

/** JDK-only map DTOs bridge the Bukkit and Forge classloaders. */
public final class FeudalMap implements CommandExecutor,TabCompleter,Listener {
    private final FeudalPlugin plugin;private final FeudalService s;private final TownyBridge towny;private final DiplomacyService diplomacy;private final SuccessionService succession;
    private static final class Menu implements InventoryHolder {final UUID owner;final List<String> estates;Inventory inventory;Menu(UUID owner,List<String> estates){this.owner=owner;this.estates=estates;}public Inventory getInventory(){return inventory;}}
    public FeudalMap(FeudalPlugin p,FeudalService s,TownyBridge t,DiplomacyService d,SuccessionService h) throws Exception {plugin=p;this.s=s;towny=t;diplomacy=d;succession=h;s.db.execute("CREATE TABLE IF NOT EXISTS map_sites (id VARCHAR(36) PRIMARY KEY,estate VARCHAR(80),kind VARCHAR(16),name VARCHAR(48),world VARCHAR(100),x INT,z INT)");}
    List<Estate> chain(String id) throws Exception {var result=new ArrayList<Estate>();var seen=new HashSet<String>();while(id!=null&&seen.add(id)&&result.size()<32){var e=s.estate(id);if(e.active())result.add(e);if(e.kind()==Kind.KINGDOM)break;id=s.parent(id);}return result;}
    private String title(Estate e) throws Exception {String parent=s.parent(e.id());return e.kind().label+" «"+e.name()+"»\nПравитель: "+towny.playerName(e.lord())+"\nСюзерен: "+(parent==null?"немає":s.estate(parent).name())+"\n"+(e.nation()==null?"":diplomacy.relations(e.nation()))+"\nShift + ЛКМ: картка володіння";}
    private int color(Estate e){if(e.kind()==Kind.KINGDOM)try{var n=TownyAPI.getInstance().getNation(UUID.fromString(e.id().substring(2)));if(n!=null&&n.getMapColorHexCode()!=null){String hex=n.getMapColorHexCode().replaceFirst("^(#|0[xX])","");if(hex.matches("[0-9a-fA-F]{6}"))return Integer.parseInt(hex,16);}}catch(IllegalArgumentException ignored){}return java.awt.Color.HSBtoRGB((e.id().hashCode()&0x7fffffff)/(float)Integer.MAX_VALUE,0.65f,0.9f)&0xffffff;}
    private Map<String,Object> dto(String id,String name,String world,int color,int size,Set<List<Integer>> cells,String title,int layer,boolean marker){return Map.of("id",id,"name",name,"world",world,"color",color,"cellSize",size,"cells",List.copyOf(cells),"title",title,"layer",layer,"marker",marker);}
    public List<Map<String,Object>> snapshot(boolean independentTowns) throws Exception {
        require(Bukkit.isPrimaryThread(),"Мапа читається лише в серверному потоці.");towny.sync();Map<String,Set<List<Integer>>> groups=new TreeMap<>();Map<String,Estate> owners=new HashMap<>();Map<String,String> worlds=new HashMap<>();int size=Coord.getCellSize();
        for(Town t:TownyAPI.getInstance().getTowns()){if(!independentTowns&&!t.hasNation())continue;var chain=chain(TownyBridge.townId(t));for(TownBlock b:t.getTownBlocks())for(Estate e:chain){String world=b.getWorld().getName(),id=e.id()+"/"+world;groups.computeIfAbsent(id,k->new HashSet<>()).add(List.of(b.getX(),b.getZ()));owners.put(id,e);worlds.put(id,world);}}
        var result=new ArrayList<Map<String,Object>>();for(var g:groups.entrySet()){var e=owners.get(g.getKey());result.add(dto("feudal/"+g.getKey(),e.kind().label+" · "+e.name(),worlds.get(g.getKey()),color(e),size,g.getValue(),title(e),1004-e.kind().level,false));}
        for(Nation n:TownyAPI.getInstance().getNations()){var capital=n.getCapital();if(capital==null)continue;var at=capital.getSpawnOrNull();if(at==null)continue;var e=s.estate(TownyBridge.nationId(n));result.add(marker("capital/"+e.id(),"★ "+e.name(),e,at.getWorld().getName(),at.getBlockX(),at.getBlockZ(),"Столиця · "+capital.getName(),0xffcc22));}
        for(var site:s.db.query("SELECT * FROM map_sites")){var e=s.estate(string(site,"estate"));if(!e.active())continue;boolean capital=string(site,"kind").equals("CAPITAL");result.add(marker("site/"+string(site,"id"),(capital?"★ ":"◆ ")+string(site,"name"),e,string(site,"world"),(int)number(site,"x"),(int)number(site,"z"),capital?"Столиця володіння":"Торговий центр",capital?0xffcc22:0x33e6bb));}return List.copyOf(result);
    }
    private Map<String,Object> marker(String id,String name,Estate e,String world,int x,int z,String kind,int color) throws Exception {return dto(id,name,world,color,8,Set.of(List.of(Math.floorDiv(x,8),Math.floorDiv(z,8))),kind+"\n"+title(e),2000,true);}
    private List<Estate> at(World world,int x,int z) throws Exception {var town=TownyAPI.getInstance().getTown(new Location(world,x,64,z));return town==null?List.of():chain(TownyBridge.townId(town));}
    private static ItemStack icon(Material type,String name,List<String> lore){var item=new ItemStack(type);var m=item.getItemMeta();m.setDisplayName(name);m.setLore(lore);item.setItemMeta(m);return item;}
    private ItemStack card(Estate e) throws Exception {
        String parent=s.parent(e.id());var lore=new ArrayList<String>();lore.add("§fПравитель: "+towny.playerName(e.lord()));lore.add("§7Сюзерен: "+(parent==null?"немає":s.estate(parent).name()));var heir=succession.heir(e.id());if(heir!=null&&Objects.equals(e.lord(),string(heir,"lord"))){lore.add("§7Династія: "+string(heir,"house_name"));lore.add("§7Спадкоємець: "+towny.playerName(string(heir,"heir"))+(bool(heir,"accepted")?" ✓":" (чекає згоди)"));}
        if(e.nation()!=null)for(var pact:diplomacy.list(e.nation()))if("ACTIVE".equals(string(pact,"status"))&&number(pact,"ends")>s.now()){String other=string(pact,e.nation().equals(string(pact,"a"))?"b":"a");lore.add("§e"+DiplomacyService.Type.valueOf(string(pact,"kind")).label+": "+s.estate(other).name());lore.add("§7До: "+Instant.ofEpochMilli(number(pact,"ends")));}lore.add("§8"+e.id());return icon(switch(e.kind()){case KINGDOM -> Material.GOLDEN_HELMET;case DUCHY -> Material.PURPLE_BANNER;case COUNTY -> Material.BLUE_BANNER;case BARONY -> Material.BRICKS;},"§e"+e.kind().label+" · "+e.name(),lore);
    }
    private void show(Player p,List<Estate> estates) throws Exception {require(!estates.isEmpty(),"У цій точці немає володіння Towny.");var m=new Menu(p.getUniqueId(),estates.stream().map(Estate::id).toList());m.inventory=Bukkit.createInventory(m,54,"Володіння та дипломатія");for(int i=0;i<Math.min(estates.size(),45);i++)m.inventory.setItem(i,card(estates.get(i)));m.inventory.setItem(49,icon(Material.BOOK,"§eКартки володінь",List.of("§7Наведіть курсор для правителя й відносин.","§7Натисніть картку для договорів держави.")));p.openInventory(m.inventory);}
    private void details(Player p,String id) throws Exception {var e=s.estate(id);var m=new Menu(p.getUniqueId(),List.of());m.inventory=Bukkit.createInventory(m,54,e.kind().label+" · "+e.name());m.inventory.setItem(4,card(e));int slot=18;if(e.nation()!=null)for(var pact:diplomacy.list(e.nation()))if(slot<45&&"ACTIVE".equals(string(pact,"status"))&&number(pact,"ends")>s.now())m.inventory.setItem(slot++,icon(Material.WRITTEN_BOOK,"§e"+DiplomacyService.Type.valueOf(string(pact,"kind")).label,List.of("§f"+s.estate(string(pact,"a")).name()+" ↔ "+s.estate(string(pact,"b")).name(),"§7Умови: "+string(pact,"terms"),"§7До: "+Instant.ofEpochMilli(number(pact,"ends")),"§8"+string(pact,"id"))));p.openInventory(m.inventory);}
    @Override public boolean onCommand(CommandSender sender,Command c,String label,String[] a){try{
        require(sender instanceof Player,"Мапа доступна у грі.");var p=(Player)sender;towny.sync();
        if(a.length==3&&a[0].equals("inspect")){int x=Integer.parseInt(a[1]),z=Integer.parseInt(a[2]);require(Math.abs((long)x)<=30_000_000&&Math.abs((long)z)<=30_000_000,"Координати поза мапою.");show(p,at(p.getWorld(),x,z));return true;}
        if(a.length==2&&a[0].equals("info")){show(p,chain(s.resolve(a[1]).id()));return true;}
        if(a.length==1&&a[0].equals("sites")){for(var r:s.db.query("SELECT * FROM map_sites ORDER BY estate,name"))plugin.message(p,string(r,"id")+" · "+string(r,"name")+" · "+string(r,"world")+" "+number(r,"x")+", "+number(r,"z"));return true;}
        if(a.length==2&&a[0].equals("remove")){var r=s.db.one("SELECT * FROM map_sites WHERE id=?",a[1]);require(r!=null,"Позначку не знайдено.");s.control(new FeudalService.Actor(p.getUniqueId().toString(),p.hasPermission("empirecraft.feudal.admin")),s.estate(string(r,"estate")));s.db.transaction(()->{s.db.execute("DELETE FROM map_sites WHERE id=?",a[1]);return null;});plugin.message(p,"Позначку прибрано.");return true;}
        if(a.length>=3&&Set.of("capital","market").contains(a[0])){var e=s.resolve(a[1]);s.control(new FeudalService.Actor(p.getUniqueId().toString(),p.hasPermission("empirecraft.feudal.admin")),e);require(at(p.getWorld(),p.getLocation().getBlockX(),p.getLocation().getBlockZ()).stream().anyMatch(x->x.id().equals(e.id())),"Позначка має бути на землі цього володіння.");boolean capital=a[0].equals("capital");require(!capital||e.kind()==Kind.DUCHY||e.kind()==Kind.COUNTY,"Столицю держави визначає Towny; тут задаються столиці герцогств і графств.");String name=validName(String.join(" ",Arrays.copyOfRange(a,2,a.length)));s.db.transaction(()->{if(capital)s.db.execute("DELETE FROM map_sites WHERE estate=? AND kind='CAPITAL'",e.id());require(number(s.db.one("SELECT COUNT(*) AS n FROM map_sites WHERE estate=?",e.id()),"n")<20,"Ліміт: 20 позначок на володіння.");s.db.execute("INSERT INTO map_sites VALUES(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),e.id(),capital?"CAPITAL":"MARKET",name,p.getWorld().getName(),p.getLocation().getBlockX(),p.getLocation().getBlockZ());return null;});plugin.message(p,"Позначка з’явиться в JourneyMap після синхронізації.");return true;}
        if(a.length==0){var here=at(p.getWorld(),p.getLocation().getBlockX(),p.getLocation().getBlockZ());if(!here.isEmpty())show(p,here);else plugin.message(p,"/realmmap info <володіння> · capital <володіння> <назва> · market <володіння> <назва> · sites · remove <ID>");return true;}throw new IllegalArgumentException("/realmmap — картка; /realmmap info <володіння> — перегляд володіння.");
    }catch(IllegalArgumentException ex){plugin.message(sender,"§c"+ex.getMessage());}catch(Exception ex){plugin.failure("Картка мапи",ex);plugin.message(sender,"§cНе вдалося прочитати мапу.");}return true;}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Menu m))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(m.owner)||e.getClickedInventory()!=m.inventory||!e.isLeftClick())return;int slot=e.getRawSlot();if(slot<0||slot>=m.estates.size())return;Bukkit.getScheduler().runTask(plugin,()->{if(p.getOpenInventory().getTopInventory()!=m.inventory)return;try{details(p,m.estates.get(slot));}catch(Exception ex){plugin.failure("Деталі володіння",ex);}});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Menu)e.setCancelled(true);}
    @Override public List<String> onTabComplete(CommandSender p,Command c,String alias,String[] a){var v=new ArrayList<String>();if(a.length==1)v.addAll(List.of("info","capital","market","sites","remove"));if(a.length==2&&Set.of("info","capital","market").contains(a[0]))try{for(var e:s.estates())if(e.active())v.add(e.id());}catch(Exception ignored){}String prefix=a[a.length-1].toLowerCase(Locale.ROOT);return v.stream().filter(x->x.toLowerCase(Locale.ROOT).startsWith(prefix)).toList();}
}
